            aOrbiterH = ((aOrbiterH + aOrbiterE) + 0xD99CD1ADEA620875ULL) + aOUSaltG[((aIndex + 207U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterH) ^ 0xBCE4898944E75298ULL;
