            //
            aOrbiterH = (((aWandererG + RotL64(aIngress, 35U)) + RotL64(aCarry, 3U)) + 0xB273937BBE1ACC2CULL) + aOASaltF[((aIndex + 156U)) & S_SALT1];
            aOrbiterA = ((aWandererJ + RotL64(aCross, 51U)) + 0xE3B96730A2F7DB5DULL) + aOASaltH[(((511U - aIndex) + 257U)) & S_SALT1];
            aOrbiterE = ((aWandererK + RotL64(aPrevious, 29U)) + 0x01D7D36E31BFB2D5ULL) + aOASaltB[((aIndex + 241U)) & S_SALT1];
            aOrbiterI = (((aWandererE + RotL64(aScatter, 19U)) + RotL64(aCarry, 19U)) + 0x698F83C0EE4A8DDCULL) + aOASaltE[(((511U - aIndex) + 142U)) & S_SALT1];
            aOrbiterB = (aWandererH + RotL64(aIngress, 11U)) + 0x2E7C449A2C4E9E73ULL;
            aOrbiterJ = (aWandererC + RotL64(aPrevious, 58U)) + 0x3E283F3D74BE158FULL;
            aOrbiterG = (((aWandererI + RotL64(aCross, 5U)) + RotL64(aCarry, 35U)) + 0x091C7D146E9436BDULL) + aOASaltC[(((511U - aIndex) + 18U)) & S_SALT1];
            //
            aOrbiterH = ((aOrbiterH + aOrbiterA) + 0x98A3115F092D9340ULL) + aOUSaltD[(((511U - aIndex) + 48U)) & S_SALT1];
            aOrbiterE = ((aOrbiterE ^ aOrbiterH) ^ 0x3E9A9E54266270CFULL) ^ aOUSaltH[((aIndex + 93U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x85188F0F24D6329FULL), 13U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterI) + 0x0576EF704F95897EULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterA) ^ 0xE3F0D761133AA261ULL) ^ aOUSaltC[((aIndex + 61U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x443CDCFB2B67DDF5ULL), 27U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterG) + 0xE5AC188B559E70F1ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterJ) ^ 0xB9FA7706F72F7C43ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x92C7937BF1A343E9ULL), 35U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterB) + 0x05AE2B83574FE69FULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterE) ^ 0x682BE0ABE922316AULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xBE90D7784DBA1F81ULL), 57U);
