            //
            aOrbiterB = (aWandererI + RotL64(aScatter, 26U)) + 0x689F9D8E2055B78FULL;
            aOrbiterE = (((aWandererE + RotL64(aIngress, 47U)) + RotL64(aCarry, 29U)) + 0xD69B03F38A1B9C04ULL) + aOASaltH[(((511U - aIndex) + 345U)) & S_SALT1];
