            aOrbiterK = (((aWandererC + RotL64(aPrevious, 35U)) + RotL64(aCarry, 11U)) + 0x87F615718652CCF2ULL) + aOASaltG[(((511U - aIndex) + 144U)) & S_SALT1];
            aOrbiterA = (aWandererA + RotL64(aCross, 11U)) + 0x81E0720AD379D0BEULL;
