            aWandererG = aWandererG + ((RotL64(aScatter, 41U) + aOrbiterA) + RotL64(aOrbiterC, 39U));
            aWandererH = aWandererH ^ ((RotL64(aCross, 3U) + RotL64(aOrbiterJ, 5U)) + aOrbiterC);
