            //
            aOrbiterK = ((aWandererH + RotL64(aScatter, 51U)) + 0x31E49CE9A1B46044ULL) + aOASaltG[(((511U - aIndex) + 345U)) & S_SALT1];
            aOrbiterB = (aWandererC + RotL64(aPrevious, 39U)) + 0xE082C889A11EF593ULL;
            aOrbiterF = (((aWandererK + RotL64(aIngress, 29U)) + RotL64(aCarry, 23U)) + 0xEDE79A59BBB2F0DCULL) + aOASaltD[((aIndex + 279U)) & S_SALT1];
