            //
            aOrbiterG = (aOrbiterG + aOrbiterK) + 0xD37ED1F25E4EC703ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterG) ^ 0x5F03A7B7F43B0C13ULL) ^ aOUSaltB[(((511U - aIndex) + 189U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x7D30A31BA5CEBB73ULL), 47U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterD) + 0x2FC6C8146E45D3CAULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterB) ^ 0x3F2E36D211202CE7ULL) ^ aOUSaltE[((aIndex + 214U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x272DF434E99B63F5ULL), 5U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterC) + 0xF4BAD742D362CD01ULL;
