            //
            aOrbiterE = (((aWandererK + RotL64(aCross, 27U)) + RotL64(aCarry, 3U)) + 0x6B865931EA65CEA2ULL) + aOASaltB[(((511U - aIndex) + 214U)) & S_SALT1];
